update ve_suppliers set status='hidden', bio_source='Sean 2026-11-05: taken down, the company says it is coming back soon, so not active' where slug='nudown';
update ve_suppliers set bio='Autron is a bag maker in Guangzhou, China. It handles sourcing, design and sampling, then follows each order through production, testing and inspection.', bio_source='Sean 2026-11-05, copied from the company site by hand' where slug='autron-industry-co-ltd';
update ve_suppliers set bio='ReNewTex is a circular economy network for the German home textiles, mattress and sun protection industries. Since 2022 its management sits with HEIMTEX, the German Home Textiles Industry Association in Wuppertal.', bio_source='Sean 2026-11-05, from the network''s own site' where slug='renewtex';
